use vstd::prelude::*;

verus! {

spec fn vec_copy(arr: Seq<i8>, result: Seq<i8>) -> bool
{
    arr.len() == result.len() &&
    forall |i: int| (0 <= i && i < arr.len()) ==> arr.index(i) == result.index(i)
}

fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures
        vec_copy(arr@, result@),
    decreases arr.len()
{
    let mut result = Vec::<i8>::new();
    let mut i: usize = 0;
    while i < arr.len()
        invariant
            i <= arr.len(),
            vec_copy(arr@.slice(0, i as int), result@.slice(0, i as int)),
        decreases arr.len() - i,
    {
        result.push(arr[i]);
        i = i + 1;
    }
    result
}

}

